INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_PROSE_EDDA','primary text','Snorri Sturluson, Prose Edda (Gylfaginning)','Primary 13th-c. Old Norse prose mythography; Gylfaginning is the systematic source for the Nine Worlds, Yggdrasil, the wells, Bifröst and the cosmological realms. Reused, already in DB.'),
 ('SRC_POETIC_EDDA','primary text','Poetic Edda','Eddic poems (Völuspá, Grímnismál, Vafþrúðnismál) attesting Ginnungagap, the Well of Urðr, Mímisbrunnr, Múspell and the realms. Reused, already in DB.')
INSERT INTO _e VALUES
 ('ENT_NORR_NINE_WORLDS','The Nine Worlds (Níu Heimar)','Cosmological category','realm-collective','Germanic/Norse','cosmology|cosmography','B','Hub collective for the nine cosmological worlds bound by Yggdrasil; Vafþrúðnismál 43 and Völuspá 2 attest ''nine worlds'' (níu heimar / níu íviðjur) though no single source enumerates them identically. Standard reconstruction (Asgard, Vanaheim, Alfheim, Midgard, Jotunheim, Svartalfheim/Nidavellir, Niflheim, Muspelheim, Hel) is modern-scholarly synthesis of Eddic material.'),
 ('ENT_NORR_ASGARD','Asgard (Ásgarðr)','Cosmological realm','divine-realm','Germanic/Norse','cosmology|divine abode','B','Stronghold of the Æsir, situated at the upper reaches of Yggdrasil and reached from Midgard by Bifröst; contains Valhalla. Gylfaginning attests its building and its halls.'),
 ('ENT_NORR_MIDGARD','Midgard (Miðgarðr)','Cosmological realm','human-realm','Germanic/Norse','cosmology|human world','B','The middle enclosure, the world of humankind, made by the sons of Borr from the brows of Ymir and encircled by Jörmungandr. Gylfaginning and Völuspá.'),
 ('ENT_NORR_VANAHEIM','Vanaheim (Vanaheimr)','Cosmological realm','divine-realm','Germanic/Norse','cosmology|divine abode','C','Home of the Vanir; named in Vafþrúðnismál 39 (Njörðr was reared in Vanaheim) and in Ynglinga saga. Sparsely described beyond its association with the Vanir.'),
 ('ENT_NORR_JOTUNHEIM','Jotunheim (Jötunheimr) / Útgarðr','Cosmological realm','giant-realm','Germanic/Norse','cosmology|giants','B','Land of the jötnar, lying outside Midgard across rivers and forests; its citadel Útgarðr features in Gylfaginning''s Útgarða-Loki episode. Jötunheimr and the outer Útgarðr are treated together here.'),
 ('ENT_NORR_NIFLHEIM','Niflheim (Niflheimr)','Cosmological realm','primordial-realm','Germanic/Norse','cosmology|primordial cold|underworld','B','World of mist and cold in the north, containing the spring Hvergelmir and the root gnawed by Níðhöggr; in Gylfaginning the primordial counterpart to fiery Múspell, and sometimes conflated with the realm of Hel.'),
 ('ENT_NORR_MUSPELHEIM','Muspelheim (Múspellsheimr)','Cosmological realm','primordial-realm','Germanic/Norse','cosmology|primordial fire','B','Realm of fire in the south, guarded by Surtr; its sparks helped form the cosmos and its hosts (Múspells synir) ride against the gods at Ragnarök. Gylfaginning; Völuspá names Múspell.'),
 ('ENT_NORR_ALFHEIM','Alfheim (Álfheimr)','Cosmological realm','elf-realm','Germanic/Norse','cosmology|elves','C','Home of the light-elves (ljósálfar), given to Freyr as a tooth-gift according to Grímnismál 5 and Gylfaginning. Lightly attested.'),
 ('ENT_NORR_SVARTALFHEIM','Svartalfheim (Svartálfaheimr) / Nidavellir','Cosmological realm','dwarf-realm','Germanic/Norse','cosmology|dwarves|smithcraft','C','Subterranean realm of the dark-elves/dwarves and their smithies; Gylfaginning sends Loki to Svartálfaheimr for the gods'' treasures. Often equated with Niðavellir (Völuspá 37), the ''dark fields'' of the dwarves; the equation is scholarly.'),
 ('ENT_NORR_VALHALLA','Valhalla (Valhöll)','Cosmological realm','afterlife-hall','Germanic/Norse','afterlife|battle-dead','B','Odin''s hall of the slain within Asgard, where the Einherjar feast and prepare for Ragnarök, served by Valkyries. Grímnismál and Gylfaginning describe its 540 doors and Sæhrímnir.'),
 ('ENT_NORR_FOLKVANGR','Folkvangr','Cosmological realm','afterlife-realm','Germanic/Norse','afterlife|battle-dead','C','Freyja''s field where she receives half of the battle-slain, the other half going to Odin; her hall there is Sessrúmnir. Grímnismál 14 and Gylfaginning.'),
 ('ENT_NORR_BIFROST','Bifröst (the rainbow bridge)','Cosmological realm','liminal-structure','Germanic/Norse','cosmology|liminal structure','B','The burning rainbow bridge (Bilröst/Bifröst) joining Midgard and Asgard, guarded by Heimdall, destined to break under the Múspell host at Ragnarök. Gylfaginning. Modeled as a locale within the realm set.'),
 ('ENT_NORR_GINNUNGAGAP','Ginnungagap','Cosmological realm','primordial-void','Germanic/Norse','cosmology|primordial void','B','The yawning primordial void between Niflheim and Muspelheim, where their rime and heat met to generate Ymir and the cosmos. Gylfaginning; Völuspá 3 (gap var ginnunga).'),
 ('ENT_NORR_URDARBRUNNR','Well of Urd (Urðarbrunnr)','Cosmological realm','sacred-well','Germanic/Norse','cosmology|fate|sacred water','B','The Well of Fate beneath a root of Yggdrasil where the gods hold court and the Norns water the tree; Völuspá 19-20 and Gylfaginning. Modeled as a sacred locale.'),
 ('ENT_NORR_MIMISBRUNNR','Well of Mimir (Mímisbrunnr)','Cosmological realm','sacred-well','Germanic/Norse','cosmology|wisdom|sacred water','B','The Well of Wisdom beneath a root of Yggdrasil, kept by Mímir; Odin pledged his eye there for a draught. Völuspá 28 and Gylfaginning. Modeled as a sacred locale.');
